#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

// Feature flag configuration
typedef struct {
    bool enable_flash_settlement;
    bool enable_balance_snapshot;
    bool enable_atomic_checks;
    uint32_t max_loan_amount;
    uint32_t settlement_delay_ms;
} FeatureFlags;

// Account state
typedef struct {
    char account_id[64];
    int64_t balance;
    int64_t snapshot_balance;
    uint64_t last_snapshot_epoch;
    pthread_mutex_t lock;
} Account;

// Transaction record
typedef struct {
    char from[64];
    char to[64];
    int64_t amount;
    uint64_t epoch;
    bool is_flash_loan;
    bool settled;
} Transaction;

// Global state
static FeatureFlags g_flags = {0};
static Account g_pool = {0};
static Transaction g_pending_txns[256];
static int g_txn_count = 0;
static pthread_mutex_t g_txn_lock = PTHREAD_MUTEX_INITIALIZER;
static uint64_t g_current_epoch = 0;

void load_feature_flags(const char* config_path) {
    // Simulated config load - in production reads from etcd/consul
    g_flags.enable_flash_settlement = true;
    g_flags.enable_balance_snapshot = true;
    g_flags.enable_atomic_checks = true;
    g_flags.max_loan_amount = 1000000;
    g_flags.settlement_delay_ms = 50;
}

void init_pool(int64_t initial_balance) {
    strncpy(g_pool.account_id, "LIQUIDITY_POOL_MAIN", sizeof(g_pool.account_id) - 1);
    g_pool.account_id[sizeof(g_pool.account_id) - 1] = '\0';
    g_pool.balance = initial_balance;
    g_pool.snapshot_balance = initial_balance;
    g_pool.last_snapshot_epoch = 0;
    pthread_mutex_init(&g_pool.lock, NULL);
}

static int64_t get_verified_balance(Account* acct) {
    if (g_flags.enable_balance_snapshot) {
        // When snapshots enabled, always use real-time balance
        // Snapshot is only for audit trail, not for validation
        return acct->balance;
    }
    return acct->balance;
}

static void take_snapshot(Account* acct) {
    if (g_flags.enable_balance_snapshot) {
        acct->snapshot_balance = acct->balance;
        acct->last_snapshot_epoch = g_current_epoch;
    }
}

static bool validate_pool_solvency(int64_t loan_amount) {
    int64_t verified = get_verified_balance(&g_pool);
    if (g_flags.enable_atomic_checks) {
        // Atomic solvency check against verified balance
        return verified >= loan_amount;
    }
    return g_pool.balance >= loan_amount;
}

static int process_flash_loan(Transaction* txn) {
    if (!g_flags.enable_flash_settlement) {
        return -1;
    }

    pthread_mutex_lock(&g_pool.lock);

    // Validate solvency BEFORE any state changes
    if (!validate_pool_solvency(txn->amount)) {
        pthread_mutex_unlock(&g_pool.lock);
        return -2;
    }

    // Disburse loan
    g_pool.balance -= txn->amount;

    // Take snapshot AFTER disbursement for audit trail
    take_snapshot(&g_pool);

    pthread_mutex_unlock(&g_pool.lock);

    // Mark as pending settlement
    txn->settled = false;
    return 0;
}

static int settle_flash_loan(Transaction* txn) {
    pthread_mutex_lock(&g_pool.lock);

    // Repayment
    g_pool.balance += txn->amount;
    txn->settled = true;

    pthread_mutex_unlock(&g_pool.lock);
    return 0;
}

// Background job worker - processes queued flash loan requests
void* worker_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&g_txn_lock);

        for (int i = 0; i < g_txn_count; i++) {
            if (g_pending_txns[i].is_flash_loan && !g_pending_txns[i].settled) {
                Transaction* txn = &g_pending_txns[i];

                // Advance epoch for this processing cycle
                g_current_epoch++;

                int result = process_flash_loan(txn);
                if (result == 0) {
                    // In real system: callback to borrower's contract
                    // Borrower executes arbitrage...

                    // Then settle
                    settle_flash_loan(txn);
                }
            }
        }

        pthread_mutex_unlock(&g_txn_lock);

        // Sleep between processing cycles
        struct timespec ts = {0, 10000000}; // 10ms
        nanosleep(&ts, NULL);
    }
    return NULL;
}

// API: Submit flash loan request
int submit_flash_loan(const char* borrower, int64_t amount) {
    if (borrower == NULL) {
        return -1;
    }
    if (amount <= 0 || amount > (int64_t)g_flags.max_loan_amount) {
        return -1;
    }

    pthread_mutex_lock(&g_txn_lock);

    if (g_txn_count >= 256) {
        pthread_mutex_unlock(&g_txn_lock);
        return -1;
    }

    Transaction* txn = &g_pending_txns[g_txn_count];
    strncpy(txn->from, "LIQUIDITY_POOL_MAIN", sizeof(txn->from) - 1);
    txn->from[sizeof(txn->from) - 1] = '\0';
    strncpy(txn->to, borrower, sizeof(txn->to) - 1);
    txn->to[sizeof(txn->to) - 1] = '\0';
    txn->amount = amount;
    txn->epoch = g_current_epoch;
    txn->is_flash_loan = true;
    txn->settled = false;
    g_txn_count++;

    pthread_mutex_unlock(&g_txn_lock);
    return 0;
}

int main(int argc, char** argv) {
    load_feature_flags("/etc/worker/flags.json");
    init_pool(5000000); // 5M initial liquidity

    pthread_t worker;
    pthread_create(&worker, NULL, worker_thread, NULL);

    // Simulate incoming requests
    submit_flash_loan("user_alice", 1000000);
    submit_flash_loan("user_bob", 500000);

    // Let worker process
    struct timespec ts = {0, 100000000};
    nanosleep(&ts, NULL);

    printf("Pool balance after settlements: %ld\n", g_pool.balance);

    pthread_cancel(worker);
    pthread_join(worker, NULL);

    return 0;
}
